export const CURIOSITIES=[
  {...base,id:'life',title:pair('Le jeu de la vie','The Game of Life'),short:pair('Jeu de la vie','Game of Life'),
    intro:pair('Une grille, deux règles, aucune intervention : des formes clignotent, voyagent, se multiplient ou meurent.','A grid, two rules, no intervention: shapes blink, travel, multiply or die.'),
    steps:[pair('Lance le planeur et compte les générations avant qu’il retrouve sa forme.','Play the glider and count the generations before it takes its shape again.'),pair('Dessine trois cases alignées, puis un carré de quatre cases. Lesquelles bougent ?','Draw three cells in a row, then a block of four. Which ones move?'),pair('Lance le R-pentomino : cinq cases seulement. Prédis ce qui va se passer avant de regarder.','Play the R-pentomino: only five cells. Predict what will happen before you watch.')],
    quiz:pair('Un planeur reprend sa forme, décalé d’une case en diagonale, au bout de combien de générations ?','A glider takes its shape again, shifted one cell diagonally, after how many generations?'),answer:4,
    explain:pair('Après 4 générations, le planeur a la même forme, décalé d’une case vers la droite et d’une vers le bas : il avance d’une case toutes les 4 générations.','After 4 generations the glider has the same shape, shifted one cell right and one cell down: it travels one cell every 4 generations.'),
    history:pair('Conway · 1970','Conway · 1970'),
    story:pair('John Horton Conway cherchait une règle très simple dont l’évolution reste imprévisible. Martin Gardner la présente en octobre 1970 dans sa rubrique de Scientific American ; des lecteurs du monde entier envoient leurs découvertes, dont le canon à planeurs de Bill Gosper la même année. L’idée d’automate cellulaire remonte à John von Neumann et Stanislaw Ulam, qui cherchaient une machine capable de se reproduire.','John Horton Conway was looking for a very simple rule whose evolution stays unpredictable. Martin Gardner presented it in October 1970 in his Scientific American column; readers worldwide sent in their discoveries, among them Bill Gosper’s glider gun that same year. The idea of a cellular automaton goes back to John von Neumann and Stanislaw Ulam, who were looking for a machine able to reproduce itself.'),
    source:'https://mathshistory.st-andrews.ac.uk/Biographies/Conway/',sourceLabel:pair('Conway · MacTutor (anglais)','Conway · MacTutor'),
    reasoning:{conjecture:pair('Une configuration finie peut disparaître, se figer, osciller, voyager ou grandir sans limite.','A finite pattern can die out, freeze, oscillate, travel or grow without bound.'),
      proof:pair('Chaque case ne dépend que de ses huit voisines, donc l’évolution d’un motif isolé ne dépend que de lui. Pour un oscillateur ou un vaisseau, il suffit de calculer une période : si le motif revient à sa forme, il recommencera indéfiniment. Le canon montre qu’une croissance illimitée est possible : il revient à sa forme toutes les 30 générations en ayant émis un planeur.','Each cell depends only on its eight neighbours, so an isolated pattern evolves on its own. For an oscillator or a spaceship it is enough to compute one period: once the pattern takes its shape again, it will repeat forever. The gun shows that unbounded growth is possible: it takes its shape again every 30 generations, having fired one glider.'),
      transfer:pair('À tester : deux planeurs qui se croisent. Que reste-t-il après la collision ?','Try two gliders that meet. What is left after the collision?')},
    links:['#biographies/von-neumann']},
  {...base,id:'square-packing',title:pair('Des carrés dans un carré','Squares in a square'),short:pair('Carrés dans un carré','Squares in a square'),
    intro:pair('Range des carrés de côté 1 dans le plus petit carré possible. Parfois, tourner un carré fait gagner de la place.','Fit squares of side 1 into the smallest possible square. Sometimes turning a square saves room.'),
    steps:[pair('Avec 5 carrés, essaie de faire mieux que le côté 3 sans rien tourner. Puis tourne un carré.','With 5 squares, try to beat side 3 without turning anything. Then turn one square.'),pair('Affiche la meilleure disposition connue pour 5, puis pour 10. Quel lien vois-tu ?','Show the best known packing for 5, then for 10. What link do you see?'),pair('Essaie 11 carrés : approche-toi du record de 3,877.','Try 11 squares: get close to the record of 3.877.')],
    quiz:pair('Combien de carrés de côté 1, au plus, peut-on ranger sans chevauchement dans un carré de côté 2,7 ?','At most how many squares of side 1 can be fitted without overlap into a square of side 2.7?'),answer:4,
    explain:pair('Quatre carrés tiennent dans un carré de côté 2. Pour cinq, il faut un côté d’au moins 2 + 1/√2 ≈ 2,707 (Göbel, 1979), plus que 2,7. Donc 4.','Four squares fit in a square of side 2. Five need side at least 2 + 1/√2 ≈ 2.707 (Göbel, 1979), more than 2.7. So 4.'),
    history:pair('Erdős et Graham · 1975','Erdős and Graham · 1975'),
    story:pair('Le problème a été étudié par Paul Erdős et Ronald Graham en 1975, qui se demandaient combien de place on perd quand le grand carré n’a pas un côté entier. Depuis, chercheurs et amateurs améliorent les records un par un ; Erich Friedman tient à jour la liste des meilleures dispositions connues.','Paul Erdős and Ronald Graham studied the problem in 1975, asking how much room is wasted when the big square does not have a whole-number side. Since then researchers and amateurs have improved the records one by one; Erich Friedman keeps the list of best known packings up to date.'),
    source:'https://www.combinatorics.org/ojs/index.php/eljc/article/view/DS7',sourceLabel:pair('E. Friedman, Packing Unit Squares in Squares · Electronic Journal of Combinatorics (anglais)','E. Friedman, Packing Unit Squares in Squares · Electronic Journal of Combinatorics'),
    reasoning:{conjecture:pair('Pour n carrés, il faut un côté d’au moins √n ; quand n est un carré parfait, la grille est optimale.','n squares need a side of at least √n; when n is a perfect square, the grid is optimal.'),
      proof:pair('L’aire du grand carré doit dépasser la somme des aires, n, donc son côté est au moins √n. Ce minorant est atteint par la grille quand n = k². Pour les autres n, il n’est pas atteint et l’on ne connaît le côté optimal que dans quelques cas, chacun demandant sa propre démonstration.','The area of the big square must be at least the total area n, so its side is at least √n. This bound is reached by the grid when n = k². For other n it is not reached, and the optimal side is known only in a few cases, each needing its own proof.'),
      transfer:pair('À discuter : pourquoi la disposition de 10 carrés montre-t-elle que 3 + 1/√2 suffit ?','Discuss: why does the 10-square packing show that 3 + 1/√2 is enough?')},
    links:['#biographies/erdos']},
  {...base,id:'moving-sofa',title:pair('Le canapé dans le couloir','The moving sofa'),short:pair('Canapé et couloir','Moving sofa'),
    intro:pair('Quel est le plus grand canapé qu’on peut faire passer dans un couloir de largeur 1 qui tourne à angle droit ?','What is the largest sofa that can be moved along a hallway of width 1 with a right-angled turn?'),
    steps:[pair('Essaie un rectangle de largeur 1, puis allonge-le. À partir de quand reste-t-il coincé ?','Try a rectangle of width 1, then make it longer. From when does it get stuck?'),pair('Choisis la famille de Hammersley avec r = 0, puis augmente r. L’aire monte-t-elle toujours ?','Choose Hammersley’s family with r = 0, then increase r. Does the area always go up?'),pair('Dessine ton propre canapé et essaie de battre 2,2074.','Draw your own sofa and try to beat 2.2074.')],
    quiz:pair('Dans la famille de Hammersley, quelle est l’aire du canapé de paramètre r = 1 ?','In Hammersley’s family, what is the area of the sofa with parameter r = 1?'),answer:2,
    explain:pair('L’aire vaut π/2 + 2r − πr²/2 ; pour r = 1 : π/2 + 2 − π/2 = 2. Le maximum est atteint pour r = 2/π, avec π/2 + 2/π ≈ 2,2074.','The area is π/2 + 2r − πr²/2; for r = 1: π/2 + 2 − π/2 = 2. The maximum is reached at r = 2/π, with π/2 + 2/π ≈ 2.2074.'),
    history:pair('Moser · 1966','Moser · 1966'),
    story:pair('Leo Moser pose le problème en 1966. John Hammersley trouve en 1968 un canapé d’aire π/2 + 2/π et montre qu’on ne peut pas dépasser 2√2. Joseph Gerver propose en 1992 une forme un peu plus grande, d’aire environ 2,2195. En 2024, Jineon Baek annonce une démonstration que le canapé de Gerver est optimal ; elle est en cours de vérification.','Leo Moser posed the problem in 1966. John Hammersley found in 1968 a sofa of area π/2 + 2/π and showed that 2√2 cannot be exceeded. Joseph Gerver proposed in 1992 a slightly larger shape, of area about 2.2195. In 2024 Jineon Baek announced a proof that Gerver’s sofa is optimal; it is being checked.'),
    source:'https://arxiv.org/abs/2411.19826',sourceLabel:pair('J. Baek, Optimality of Gerver’s sofa · arXiv (anglais)','J. Baek, Optimality of Gerver’s sofa · arXiv'),
    reasoning:{conjecture:pair('Dans la famille de Hammersley, l’aire est la plus grande pour r = 2/π, et chaque canapé de la famille passe le coin.','In Hammersley’s family the area is largest for r = 2/π, and every sofa of the family goes round the corner.'),
      proof:pair('Le canapé est formé de deux quarts de disque (aire π/2 en tout) et d’un rectangle 2r × 1 privé d’un demi-disque de rayon r : A(r) = π/2 + 2r − πr²/2. A′(r) = 2 − πr s’annule pour r = 2/π, où A est maximale. Pour tourner, le canapé pivote d’un quart de tour pendant que le centre de l’encoche parcourt le cercle de rayon r autour du coin intérieur : le coin reste dans l’encoche, les quarts de disque restent contre les murs extérieurs.','The sofa is made of two quarter discs (area π/2 in all) and a 2r × 1 rectangle minus a half disc of radius r: A(r) = π/2 + 2r − πr²/2. A′(r) = 2 − πr vanishes at r = 2/π, where A is largest. To turn, the sofa rotates a quarter turn while the centre of the notch runs round the circle of radius r about the inner corner: the corner stays in the notch, the quarter discs stay against the outer walls.'),
      transfer:pair('À discuter : pourquoi un canapé plus large que le couloir ne peut-il jamais passer, quelle que soit sa forme ?','Discuss: why can a sofa wider than the hallway never pass, whatever its shape?')},
    links:[]},
  {...base,id:'inscribed-square',title:pair('Un carré sur chaque courbe ?','A square on every curve?'),short:pair('Carré inscrit','Inscribed square'),
    intro:pair('Dessine n’importe quelle courbe fermée : on y trouve quatre points qui forment un carré. Toujours ? Personne ne le sait.','Draw any closed curve: four of its points form a square. Always? Nobody knows.'),
    steps:[pair('Compare le triangle acutangle et le triangle obtusangle : combien de carrés chacun contient-il ?','Compare the acute and the obtuse triangle: how many squares does each contain?'),pair('Dessine une courbe très tordue. La recherche trouve-t-elle encore un carré ?','Draw a very twisted curve. Does the search still find a square?'),pair('Règle le rapport des côtés sur 2 : cherche des rectangles deux fois plus longs que larges.','Set the ratio of the sides to 2: look for rectangles twice as long as they are wide.')],
    quiz:pair('Combien de carrés inscrits (quatre sommets sur le bord) contient un triangle dont les trois angles sont aigus ?','How many inscribed squares (four corners on the boundary) does a triangle with three acute angles contain?'),answer:3,
    explain:pair('Quatre sommets sur trois côtés : deux sont sur le même côté, donc le carré a un côté posé sur un côté du triangle. Sur la base a de hauteur h, le carré de côté s = ah/(a + h) tient si le pied de la hauteur tombe dans la base, ce qui arrive pour les trois côtés quand les trois angles sont aigus.','Four corners on three sides: two lie on the same side, so the square has a side lying on a side of the triangle. On base a with height h, the square of side s = ah/(a + h) fits when the foot of the height falls inside the base, which happens for all three sides when the three angles are acute.'),
    history:pair('Toeplitz · 1911','Toeplitz · 1911'),
    story:pair('Otto Toeplitz pose la question en 1911. Arnold Emch la résout pour les courbes convexes en 1913, Lev Schnirelmann pour les courbes lisses en 1929. Pour une courbe continue quelconque, qui peut zigzaguer à toutes les échelles, le problème est toujours ouvert. En 2020, Joshua Greene et Andrew Lobb montrent que toute courbe lisse contient des rectangles inscrits de toutes les formes.','Otto Toeplitz asked the question in 1911. Arnold Emch solved it for convex curves in 1913, Lev Schnirelmann for smooth curves in 1929. For an arbitrary continuous curve, which may zigzag at every scale, the problem is still open. In 2020 Joshua Greene and Andrew Lobb showed that every smooth curve contains inscribed rectangles of every shape.'),
    source:'https://arxiv.org/abs/2005.09193',sourceLabel:pair('J. Greene et A. Lobb, The rectangular peg problem · arXiv (anglais)','J. Greene and A. Lobb, The rectangular peg problem · arXiv'),
    reasoning:{conjecture:pair('Toute courbe fermée qui ne se croise pas contient quatre points formant un carré.','Every closed curve that does not cross itself contains four points forming a square.'),
      proof:pair('Démontré pour les courbes convexes, lisses ou polygonales régulières, ouvert en général. Pour les triangles, on peut tout compter : un carré inscrit a un côté sur un côté du triangle (deux de ses sommets sont sur le même côté), et le théorème de Thalès donne son côté ah/(a + h).','Proved for convex, smooth or well-behaved curves, open in general. For triangles everything can be counted: an inscribed square has a side on a side of the triangle (two of its corners lie on the same side), and similar triangles give its side ah/(a + h).'),
      transfer:pair('À tester : un cercle contient une infinité de carrés inscrits. Une ellipse en contient-elle plusieurs ?','Try it: a circle contains infinitely many inscribed squares. Does an ellipse contain several?')},
    links:[]},
  {...base,id:'opaque-square',title:pair('Le carré opaque','The opaque square'),short:pair('Carré opaque','Opaque square'),
    intro:pair('Construis le mur le plus court possible pour que personne ne puisse voir à travers un carré, dans aucune direction.','Build the shortest possible wall so that nobody can see through a square, in any direction.'),
    steps:[pair('Supprime un côté de la barrière « trois côtés » : trouve une direction où la lumière passe.','Remove one side of the “three sides” barrier: find a direction where light gets through.'),pair('Compare les diagonales et l’arbre de Steiner. Lequel est le plus court ?','Compare the diagonals and the Steiner tree. Which is shorter?'),pair('Pars de rien et construis ta barrière. Peux-tu descendre sous 2,7 ?','Start from nothing and build your barrier. Can you go below 2.7?')],
    quiz:pair('Parmi les quatre côtés d’un carré, combien faut-il en garder, au minimum, pour qu’aucune droite ne traverse le carré sans les rencontrer ?','Of the four sides of a square, at least how many must be kept so that no line crosses the square without meeting them?'),answer:3,
    explain:pair('Avec deux côtés opposés, les droites parallèles à ces côtés passent entre eux. Avec deux côtés voisins, une droite qui coupe les deux autres côtés près du coin opposé passe sans les toucher. Trois côtés suffisent : une droite qui traverse le carré coupe son bord en deux points, et au plus un est sur le côté manquant.','With two opposite sides, the lines parallel to them pass between them. With two neighbouring sides, a line cutting the other two sides near the opposite corner passes without touching them. Three sides are enough: a line crossing the square meets its boundary in two points, at most one of them on the missing side.'),
    history:pair('Mazurkiewicz · 1916','Mazurkiewicz · 1916'),
    story:pair('Stefan Mazurkiewicz introduit les ensembles opaques en 1916 ; Frederick Bagemihl pose en 1959 la question de leur longueur minimale. Pour le carré, la meilleure barrière connue mesure √2 + √6/2 ≈ 2,639. Le minorant 2 date de 1964 ; il n’a été amélioré qu’en 2019, à 2,00002.','Stefan Mazurkiewicz introduced opaque sets in 1916; Frederick Bagemihl asked for their least length in 1959. For the square, the best known barrier has length √2 + √6/2 ≈ 2.639. The lower bound 2 dates from 1964; it was only improved in 2019, to 2.00002.'),
    source:'https://arxiv.org/abs/1311.3323',sourceLabel:pair('A. Dumitrescu et M. Jiang, The opaque square · arXiv (anglais)','A. Dumitrescu and M. Jiang, The opaque square · arXiv'),
    reasoning:{conjecture:pair('Toute barrière opaque du carré de côté 1 mesure au moins 2.','Every opaque barrier of the unit square has length at least 2.'),
      proof:pair('Dans chaque direction, l’ombre des segments doit recouvrir l’ombre du carré : la somme de leurs projections dépasse la largeur du carré dans cette direction. Faisons la moyenne sur toutes les directions : un segment de longueur ℓ a une projection moyenne 2ℓ/π, et le carré une largeur moyenne égale à son périmètre divisé par π, soit 4/π (formule de Cauchy). Donc 2L/π ≥ 4/π, c’est-à-dire L ≥ 2.','In every direction the shadow of the segments must cover the shadow of the square: the sum of their projections exceeds the width of the square in that direction. Average over all directions: a segment of length ℓ has mean projection 2ℓ/π, and the square has mean width equal to its perimeter divided by π, that is 4/π (Cauchy’s formula). So 2L/π ≥ 4/π, that is L ≥ 2.'),
      transfer:pair('À discuter : la meilleure barrière connue n’est pas d’un seul tenant. Pourquoi un morceau détaché peut-il aider ?','Discuss: the best known barrier is not in one piece. Why can a detached piece help?')},
    links:[]},
];
